#!/usr/bin/env node
// Generates src-web/protocol/generated.ts from sugar-crush's protocol schema
// (sugar-crush/docs/protocol/sugarcrush.v1.schema.json, itself generated from
// the PHP value objects by sugar-crush's scripts/gen-protocol-schema.php).
//
//   npm run gen:protocol            rewrite generated.ts
//   npm run gen:protocol -- --check exit 1 when generated.ts is stale
//
// SCHEMA_PATH overrides where the schema is read from; the default is the
// monorepo sibling. A split-repo clone has no sibling, and needs none: the
// generated file is committed, so building the UI never runs this.
//
// A small purpose-built converter rather than json-schema-to-typescript: the
// schema uses a narrow subset of JSON Schema (type, properties, required,
// items, enum, oneOf, $ref to $defs, additionalProperties), and the output
// also needs the protocol's own maps — method => {params, result},
// event => data, the scopes and the durable flags — which a generic tool
// does not know about. The output is deterministic: schema order, no dates.

import { readFileSync, writeFileSync } from 'node:fs'
import { dirname, relative, resolve } from 'node:path'
import { fileURLToPath } from 'node:url'

const here = dirname(fileURLToPath(import.meta.url))
const root = resolve(here, '..')
const schemaPath = resolve(process.env.SCHEMA_PATH ?? resolve(root, '../sugar-crush/docs/protocol/sugarcrush.v1.schema.json'))
const outPath = resolve(root, 'src-web/protocol/generated.ts')

const IDENT = /^[A-Za-z_$][A-Za-z0-9_$]*$/

function key(name) {
  return IDENT.test(name) ? name : JSON.stringify(name)
}

function doc(text, indent) {
  if (typeof text !== 'string' || text === '') return ''
  const safe = text.replace(/\*\//g, '*\\/')
  return `${indent}/** ${safe} */\n`
}

function literal(value) {
  return JSON.stringify(value)
}

function paren(type) {
  return /[|&]/.test(type) && !/^\(.*\)$/.test(type) ? `(${type})` : type
}

function union(types) {
  const unique = [...new Set(types)]
  if (unique.includes('unknown')) return 'unknown'
  return unique.join(' | ')
}

/** The TypeScript type a schema node describes. */
export function toType(node, indent = '') {
  if (node === true || node === undefined) return 'unknown'
  if (node === false) return 'never'
  if (typeof node !== 'object' || node === null) return 'unknown'

  if (typeof node.$ref === 'string') {
    const match = /^#\/\$defs\/(.+)$/.exec(node.$ref)
    if (!match) throw new Error(`unsupported $ref ${node.$ref}`)
    return match[1]
  }
  if ('const' in node) return literal(node.const)
  if (Array.isArray(node.enum)) return union(node.enum.map(literal))
  for (const combinator of ['oneOf', 'anyOf']) {
    if (Array.isArray(node[combinator])) {
      return union(node[combinator].map((branch) => toType(branch, indent)))
    }
  }

  const types = Array.isArray(node.type) ? node.type : node.type === undefined ? [] : [node.type]
  if (types.length === 0) {
    return node.properties || node.additionalProperties !== undefined ? objectType(node, indent) : 'unknown'
  }

  return union(types.map((type) => {
    switch (type) {
      case 'string':
        return 'string'
      case 'integer':
      case 'number':
        return 'number'
      case 'boolean':
        return 'boolean'
      case 'null':
        return 'null'
      case 'array':
        return node.items === undefined ? 'unknown[]' : `${paren(toType(node.items, indent))}[]`
      case 'object':
        return objectType(node, indent)
      default:
        throw new Error(`unsupported type ${type}`)
    }
  }))
}

function objectType(node, indent) {
  const props = node.properties ?? {}
  const names = Object.keys(props)
  const extra = node.additionalProperties
  if (names.length === 0) {
    if (extra === false) return 'Record<string, never>'
    return `Record<string, ${extra === undefined || extra === true ? 'unknown' : toType(extra, indent)}>`
  }

  const required = new Set(node.required ?? [])
  const inner = `${indent}  `
  let out = '{\n'
  for (const name of names) {
    out += doc(props[name]?.description, inner)
    out += `${inner}${key(name)}${required.has(name) ? '' : '?'}: ${toType(props[name], inner)}\n`
  }
  if (extra !== undefined && extra !== false) {
    out += `${inner}[key: string]: unknown\n`
  }

  return `${out}${indent}}`
}

export function generate(schema, schemaLabel) {
  const lines = []
  // An undefined line (an absent description) is dropped below.
  const push = (text) => lines.push(text === undefined ? undefined : text)

  push(`// GENERATED by scripts/gen-protocol.mjs from ${schemaLabel} — do not edit.`)
  push('// Run `npm run gen:protocol` after the server protocol changes.')
  push('')
  push(`/** The protocol major this client speaks (\`server.hello\` min/max). */`)
  push(`export const PROTOCOL = ${literal(schema.protocol)} as const`)
  push('')
  push('export type Scope = \'read\' | \'write\' | \'approve\' | \'admin\'')
  push('')

  for (const [name, node] of Object.entries(schema.$defs ?? {})) {
    push(doc(node.description, '').trimEnd() || undefined)
    const type = toType(node, '')
    // An interface only for a plain object; a union of objects is an alias.
    if (node.type === 'object' && !node.oneOf && !node.anyOf && type.startsWith('{')) {
      push(`export interface ${name} ${type}`)
    } else {
      push(`export type ${name} = ${type}`)
    }
    push('')
  }

  push('/** Every method: its params and its result. */')
  push('export interface Methods {')
  for (const [name, method] of Object.entries(schema.methods ?? {})) {
    push(doc(method.description, '  ').trimEnd() || undefined)
    push(`  ${key(name)}: {`)
    push(`    params: ${toType(method.params, '    ')}`)
    push(`    result: ${toType(method.result, '    ')}`)
    push('  }')
  }
  push('}')
  push('')
  push('export type MethodName = keyof Methods')
  push('export type MethodParams<M extends MethodName> = Methods[M][\'params\']')
  push('export type MethodResult<M extends MethodName> = Methods[M][\'result\']')
  push('')
  push('/** The scope each method needs. */')
  push('export const METHOD_SCOPES: { readonly [M in MethodName]: Scope } = {')
  for (const [name, method] of Object.entries(schema.methods ?? {})) {
    push(`  ${key(name)}: ${literal(method.scope)},`)
  }
  push('}')
  push('')
  push('/** The methods that accept an `idempotencyKey`. */')
  push('export const IDEMPOTENT_METHODS: readonly MethodName[] = [')
  for (const [name, method] of Object.entries(schema.methods ?? {})) {
    if (method.idempotent === true) push(`  ${literal(name)},`)
  }
  push(']')
  push('')

  push('/** Every event type: the shape of its `data`. */')
  push('export interface Events {')
  for (const [name, event] of Object.entries(schema.events ?? {})) {
    push(doc(event.description, '  ').trimEnd() || undefined)
    push(`  ${key(name)}: ${toType(event.data, '  ')}`)
  }
  push('}')
  push('')
  push('export type EventName = keyof Events')
  push('')
  push('/** Whether each event type is durable (logged, carries a `seq`) and its scope. */')
  push('export const EVENT_KINDS: { readonly [E in EventName]: { readonly durable: boolean; readonly scope: \'session\' | \'server\' } } = {')
  for (const [name, event] of Object.entries(schema.events ?? {})) {
    push(`  ${key(name)}: { durable: ${event.durable === true}, scope: ${literal(event.scope)} },`)
  }
  push('}')

  return lines.filter((line) => line !== undefined).join('\n') + '\n'
}

function main() {
  const check = process.argv.includes('--check')
  let raw
  try {
    raw = readFileSync(schemaPath, 'utf8')
  } catch {
    console.error(`gen:protocol: no schema at ${schemaPath} (set SCHEMA_PATH, or run inside the monorepo)`)
    process.exit(2)
  }
  // A fixed label, so the output does not depend on where the schema was read.
  const output = generate(JSON.parse(raw), 'sugar-crush/docs/protocol/sugarcrush.v1.schema.json')

  if (check) {
    let current = ''
    try {
      current = readFileSync(outPath, 'utf8')
    } catch {
      // missing counts as stale
    }
    if (current !== output) {
      console.error('gen:protocol: src-web/protocol/generated.ts is stale — run `npm run gen:protocol`')
      process.exit(1)
    }
    console.log('gen:protocol: generated.ts is up to date')
    return
  }

  writeFileSync(outPath, output)
  console.log(`gen:protocol: wrote ${relative(root, outPath)}`)
}

if (process.argv[1] && resolve(process.argv[1]) === fileURLToPath(import.meta.url)) {
  main()
}
